const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Helper function to mask clouds in Landsat SR data (C2).
function maskL457sr(image) {
  const qa = image.select('QA_PIXEL');
  // dilated cloud, cloud, cloud shadow, and snow bits
  const cloud = qa.bitwiseAnd(1 << 5)
                  .or(qa.bitwiseAnd(1 << 7))
                  .or(qa.bitwiseAnd(1 << 3))
                  .or(qa.bitwiseAnd(1 << 4));
  // Get the internal mask and combine it with the cloud mask.
  const mask = image.mask().and(cloud.not());
  return image.updateMask(mask)
      .select(['SR_B3', 'SR_B4', 'SR_B5']) // NIR, Red, SWIR1
      .copyProperties(image, ["system:time_start"]);
}

// Function to calculate NDBI for Landsat 5/7
function calculateNDBI(image) {
    return image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDBI');
}

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([36.4333, -0.7167]).buffer(10000); // Naivasha, Kenya, with a 10km buffer
  const startYear1 = '1985-01-01';
  const endYear1 = '1987-12-31'; // Centered on 1986
  const startYear2 = '1999-01-01';
  const endYear2 = '2001-12-31'; // Centered on 2000

  // 2. Data Acquisition
  const collection1986 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(aoi)
      .filterDate(startYear1, endYear1);

  const collection2000 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
      .filterBounds(aoi)
      .filterDate(startYear2, endYear2);

  // 3. Data Checks
  const size1986 = collection1986.size().getInfo();
  const size2000 = collection2000.size().getInfo();

  if (size1986 === 0 || size2000 === 0) {
    console.log(`Image count 1986: ${size1986}`);
    console.log(`Image count 2000: ${size2000}`);
    console.log("Empty collection for one or both periods.");
    console.log("A: Yes");
    return;
  }

  // 4. Processing
  const image1986 = collection1986.map(maskL457sr).median();
  const image2000 = collection2000.map(maskL457sr).median();

  const ndbi1986 = calculateNDBI(image1986);
  const ndbi2000 = calculateNDBI(image2000);

  // Threshold to identify urban areas (NDBI > 0 is a common threshold)
  const urbanThreshold = 0;
  const urban1986 = ndbi1986.gt(urbanThreshold);
  const urban2000 = ndbi2000.gt(urbanThreshold);

  const areaImage = ee.Image.pixelArea(); // Area in sq meters

  const urbanArea1986 = urban1986.multiply(areaImage).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  });

  const urbanArea2000 = urban2000.multiply(areaImage).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  });

  const area1986_sqkm = ee.Number(urbanArea1986.get('NDBI')).divide(1e6).getInfo();
  const area2000_sqkm = ee.Number(urbanArea2000.get('NDBI')).divide(1e6).getInfo();

  // 5. Validation & Final Answer
  if (area1986_sqkm === null || area2000_sqkm === null) {
      console.log(`1986 Urban Area: ${area1986_sqkm}`);
      console.log(`2000 Urban Area: ${area2000_sqkm}`);
      console.log("Calculation resulted in null.");
      console.log("C3: Calculation Failure");
      return;
  }

  if (area1986_sqkm === 0 && area2000_sqkm === 0) {
      console.log(`1986 Urban Area (sqkm): ${area1986_sqkm.toFixed(2)}`);
      console.log(`2000 Urban Area (sqkm): ${area2000_sqkm.toFixed(2)}`);
      console.log("No valid pixels identified as urban in either period.");
      console.log("C2: No Valid Pixels");
      return;
  }

  console.log(`Image count 1986 period: ${size1986}`);
  console.log(`Image count 2000 period: ${size2000}`);
  console.log(`1986 Est. Urban Area (sqkm): ${area1986_sqkm.toFixed(2)}`);
  console.log(`2000 Est. Urban Area (sqkm): ${area2000_sqkm.toFixed(2)}`);

  if (area2000_sqkm > area1986_sqkm) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
});
